def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    alive_opponents = []
    prev_bids = []
    opp_requirements = []
    for opp in opponents_status.values():
        if opp.get('alive'):
            alive_opponents.append(opp)
            opp_requirements.append(opp.get('water_requirement', WATER_REQ))
            prev = opp.get('previous_trace', {})
            if prev and prev.get('bid') is not None:
                prev_bids.append(float(prev['bid']))

    if budget <= 0:
        return 0.0

    if not alive_opponents:
        if hp <= 2 or no_water >= 1:
            return float(min(budget, DAILY_SALARY * 0.9))
        return float(min(budget, DAILY_SALARY * 0.25))

    total_players = 1 + len(alive_opponents)
    total_req = WATER_REQ
    for r in opp_requirements:
        total_req += r

    scarcity = total_req / max(supply, 1.0)
    per_capita = supply / max(total_players, 1)
    urgent = (hp <= 2) or (no_water >= 2)
    pressured = (hp <= 4) or (no_water >= 1)

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = (sum(prev_bids) / len(prev_bids)) if prev_bids else 0.0

    if urgent:
        base = max(DAILY_SALARY * 0.95, highest_prev + 4.0)
    elif scarcity >= 2.8:
        base = max(DAILY_SALARY * 0.88, highest_prev + 2.5)
    elif scarcity >= 2.3:
        base = max(DAILY_SALARY * 0.72, avg_prev + 1.5)
    elif scarcity >= 1.8:
        base = max(DAILY_SALARY * 0.55, avg_prev * 0.82)
    else:
        base = DAILY_SALARY * 0.28

    if per_capita >= WATER_REQ * 1.4 and not pressured:
        base *= 0.72
    elif per_capita < WATER_REQ * 0.9:
        base *= 1.12

    rich_live = 0
    for opp in alive_opponents:
        if opp.get('budget', 0) > budget:
            rich_live += 1
    if rich_live >= 2 and not urgent:
        base *= 0.93

    if day >= 8 and hp > 5 and no_water == 0:
        base *= 0.9

    bid = min(float(budget), float(base))
    if bid < 0:
        bid = 0.0
    return float(round(bid, 2))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context.get('supply', 0.0))
    day = int(day_context.get('day', 0))

    hp = float(my_status.get('hp', 0.0))
    budget = float(my_status.get('budget', 0.0))
    no_water_days = int(my_status.get('no_water_days', 0))

    alive_opps = []
    for oid, o in opponents_status.items():
        if o.get('alive', False):
            alive_opps.append((oid, o))

    if not alive_opps:
        return min(budget, DAILY_SALARY * 0.4)

    # Read yesterday's immediate pressure from each opponent's previous_trace
    prev_bids = []
    for oid, o in alive_opps:
        prev = o.get('previous_trace', {}) or {}
        b = prev.get('bid', None)
        if b is not None:
            try:
                prev_bids.append(float(b))
            except Exception:
                pass

    highest_prev_bid = max(prev_bids) if prev_bids else 0.0
    avg_prev_bid = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    # Supply pressure: less supply -> need to outbid more
    # Map supply in [15,25] to a 0..1 pressure (1 means scarce)
    denom = float(MAX_SUPPLY - MIN_SUPPLY)
    if denom <= 0:
        scarcity = 0.5
    else:
        scarcity = (float(MAX_SUPPLY) - supply) / denom
        if scarcity < 0.0:
            scarcity = 0.0
        if scarcity > 1.0:
            scarcity = 1.0

    # If we are in danger (low hp or already accumulating no-water days), bid more aggressively.
    danger = 0.0
    if hp <= 2.0:
        danger = 1.0
    elif hp <= 4.0:
        danger = 0.7
    elif no_water_days >= 2:
        danger = 0.6
    else:
        danger = 0.25

    # Baseline target bid: try to be slightly above the best yesterday bid only when necessary.
    # If opponents were bidding high and surviving, we must match their intensity but not always exceed.
    # Use scarcity and danger to decide whether to go near-high or mid.
    if highest_prev_bid >= DAILY_SALARY * 0.85:
        # They were very aggressive; aim between 0.75x and 1.05x of highest_prev_bid depending on scarcity/danger.
        mult = 0.75 + 0.35 * scarcity + 0.25 * danger
        target = highest_prev_bid * mult
    else:
        # They were not extremely aggressive; aim around average plus a premium scaled by scarcity/danger.
        target = avg_prev_bid + (DAILY_SALARY * 0.15) + (DAILY_SALARY * 0.25) * scarcity + (DAILY_SALARY * 0.15) * danger

    # Convert target into practical bounds tied to budget.
    # Keep a reserve so we don't die from budget exhaustion.
    # Reserve fraction increases when day is late.
    episode_days = 10
    late_factor = 0.0
    if episode_days > 0:
        late_factor = float(max(0, day)) / float(episode_days)
    reserve_frac = 0.35 + 0.25 * late_factor
    max_affordable = max(0.0, budget * (1.0 - reserve_frac))

    # Also ensure we can always buy at least one day of water if possible.
    # In many implementations, bids compete for supply; we don't know exact mapping, so we use a conservative floor.
    min_bid = DAILY_SALARY * (0.35 + 0.25 * scarcity)  # don't bid too low when scarce

    bid = max(min_bid, target)

    # If budget is low, scale down.
    if max_affordable < bid:
        bid = max_affordable

    # If we are extremely low hp, override to spend more (still capped by budget).
    if danger >= 1.0:
        bid = min(budget, max(bid, DAILY_SALARY * 0.85))

    # Final cap: cannot exceed budget.
    if bid > budget:
        bid = budget

    # If bid becomes non-positive, bid minimal.
    if bid <= 0.0:
        bid = min(budget, DAILY_SALARY * 0.1)

    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 7
    DAILY_SALARY = 80
    supply = day_context['supply']
    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    if not alive_opponents:
        return float(min(my_status['budget'], 20.0))

    yesterday_bids = [o['previous_trace']['bid'] for o in alive_opponents if o.get('previous_trace') and o['previous_trace'].get('bid') is not None]

    if my_status['hp'] <= 3:
        return float(min(my_status['budget'], 75.0))

    if yesterday_bids:
        max_prev = max(yesterday_bids)
        if max_prev > 100:
            return float(min(my_status['budget'], 30.0))
        return float(min(my_status['budget'], max(40.0, max_prev * 0.6)))

    return float(min(my_status['budget'], 45.0))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 8
    SALARY = 140
    supply = day_context['supply']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    alive = [o for o in opponents_status.values() if o['alive']]
    if not alive:
        return min(budget, SALARY * 0.3)

    prev_bids = []
    for opp in alive:
        prev = opp.get('previous_trace', {})
        if prev and 'bid' in prev and prev['bid'] is not None:
            prev_bids.append(prev['bid'])

    if no_water > 0:
        base = SALARY * 0.8
    elif hp < 3:
        base = SALARY * 0.6
    else:
        base = SALARY * 0.4

    if prev_bids:
        max_prev = max(prev_bids)
        if max_prev > 100:
            if no_water > 0 or hp <= 2:
                target = max_prev + 1.0
            else:
                target = max(SALARY*0.5, max_prev + 0.5)
        else:
            if no_water > 0:
                target = max(base, max_prev + 1.5)
            else:
                target = max(base, max_prev + 0.5)
    else:
        target = base

    if supply < 18:
        target *= 1.3
    elif supply > 22:
        target *= 0.9

    return min(float(budget), target)
